      "arabic_text": "قَالَ: إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى لَيْسَ بِظَلَّامٍ لِلْعَبِيدِ، وَهُوَ أَعْلَمُ بِمَا فِي الصَّدُورِ، وَأَبْصَرُ بِمَا فِي الْأَعْيُنِ، وَأَقْرَبُ بِمَا فِي الْبُطُونِ، وَأَقْدَرُ عَلَى مَا فِي الْأَرْضِ وَالسَّمَاوَاتِ، لَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يَعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْجِزُهُ شَيْءٌ، وَلَا يَغِيبُ عَنْهُ شَيْءٌ، وَلَا يَفُوتُهُ شَيْءٌ، وَلَا يَخْفَى عَلَيْهِ شَيْءٌ، وَلَا يُعْج